begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();d uuid:=gen_random_uuid();req uuid:=gen_random_uuid();ruleid text;product uuid;coupon uuid;use_id uuid:=gen_random_uuid();pin text:=lpad((floor(random()*10000)::integer)::text,4,'0');reply jsonb;denied boolean;day date:=(now() at time zone 'Asia/Seoul')::date;
begin
 insert into auth.users(id,email) values(a,'rule-admin-'||a||'@example.invalid'),(b,'rule-member-'||b||'@example.invalid'),(c,'rule-coach-'||c||'@example.invalid'),(d,'rule-member-'||d||'@example.invalid');
 execute 'set local role service_role';
 update public.gym_members set status='approved',role=case when id=a then 'admin' when id=c then 'coach' else 'member' end where id in(a,b,c,d);
 perform public.onoff_points(a,jsonb_build_object('action','settings','enabled',true,'attendancePoints',10,'recordPoints',20,'maxBalance',20,'pin',pin));
 insert into public.gym_attendance(user_id,date) values(b,day);
 insert into public.gym_records(id,user_id,date,program,section,body,writer_id) values(gen_random_uuid(),b,'1906-01-01','B/T','S1','{}',b);
 if (select balance from public.gym_point_accounts where user_id=b)<>20 then raise exception 'award exceeded balance cap';end if;
 if (select amount from public.gym_point_ledger where user_id=b and event_key='record:'||day::text)<>10 then raise exception 'partial cap credit incorrect';end if;
 perform public.onoff_points(a,'{"action":"product-save","name":"Isolated capped gift","description":"rollback","price":15,"uses":2}');
 select id into product from public.gym_point_products where name='Isolated capped gift';
 reply:=public.onoff_points(b,jsonb_build_object('action','exchange','expectedPrice',15,'expectedUses',2,'productId',product,'requestId',gen_random_uuid()));coupon:=(reply->>'couponId')::uuid;
 if not exists(select 1 from public.gym_point_coupons where id=coupon and expires_at=((created_at at time zone 'Asia/Seoul')+interval '1 month') at time zone 'Asia/Seoul') then raise exception 'calendar-month expiry missing';end if;
 insert into public.gym_records(id,user_id,date,program,section,body,writer_id) values(gen_random_uuid(),b,'1906-01-01','WOD','S2','{}',b);
 if (select balance from public.gym_point_accounts where user_id=b)<>5 then raise exception 'B/T-WOD double award';end if;
 denied:=false;begin perform public.onoff_points(c,jsonb_build_object('action','grant','memberId',b,'requestId',req,'amount',50,'reason','Isolated grant'));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'coach granted points';end if;
 reply:=public.onoff_points(a,jsonb_build_object('action','grant','memberId',b,'requestId',req,'amount',50,'reason','Isolated grant'));
 if reply->>'granted'<>'15' then raise exception 'manual grant cap not enforced';end if;
 perform public.onoff_points(a,jsonb_build_object('action','grant','memberId',b,'requestId',req,'amount',50,'reason','Isolated grant'));
 if (select balance from public.gym_point_accounts where user_id=b)<>20 or (select count(*) from public.gym_point_grants where user_id=b)<>1 then raise exception 'manual grant retry duplicated';end if;
 perform public.onoff_points(a,'{"action":"settings","enabled":true,"maxBalance":5}');
 if (select balance from public.gym_point_accounts where user_id=b)<>20 then raise exception 'existing balance destroyed by cap';end if;
 reply:=public.onoff_points(a,jsonb_build_object('action','grant','memberId',b,'requestId',gen_random_uuid(),'amount',10,'reason','Above cap'));
 if reply->>'granted'<>'0' then raise exception 'grant above reduced cap';end if;
 perform public.onoff_points(a,'{"action":"rule-save","kind":"manual","name":"Isolated event","amount":3}');
 select id into ruleid from public.gym_point_rules where name='Isolated event';
 perform public.onoff_points(a,jsonb_build_object('action','grant','memberId',d,'requestId',gen_random_uuid(),'ruleId',ruleid,'reason','Event'));
 if (select balance from public.gym_point_accounts where user_id=d)<>3 then raise exception 'custom rule grant failed';end if;
 perform public.onoff_points(a,jsonb_build_object('action','rule-save','id',ruleid,'kind','manual','name','Renamed event','amount',4));
 perform public.onoff_points(a,jsonb_build_object('action','rule-delete','id',ruleid));
 denied:=false;begin perform public.onoff_points(a,jsonb_build_object('action','grant','memberId',d,'requestId',gen_random_uuid(),'ruleId',ruleid,'reason','Deleted event'));exception when raise_exception then denied:=true;end;if not denied then raise exception 'deleted rule granted';end if;
 perform public.onoff_points(a,'{"action":"rule-delete","id":"record"}');
 insert into public.gym_records(id,user_id,date,program,section,body,writer_id) values(gen_random_uuid(),d,'1906-01-01','WOD','S1','{}',d);
 if (select balance from public.gym_point_accounts where user_id=d)<>3 then raise exception 'deleted auto rule awarded';end if;
 perform public.onoff_points(a,'{"action":"rule-save","kind":"record","name":"Restored record","amount":2}');
 insert into public.gym_records(id,user_id,date,program,section,body,writer_id) values(gen_random_uuid(),d,'1906-01-01','WOD','S2','{}',d);
 if (select balance from public.gym_point_accounts where user_id=d)<>5 then raise exception 'restored auto rule missing';end if;
 update public.gym_point_coupons set expires_at=now()-interval '1 second' where id=coupon;
 denied:=false;begin perform public.onoff_points(b,jsonb_build_object('action','use','couponId',coupon,'requestId',use_id,'pin',pin));exception when raise_exception then if sqlerrm<>'사용기한이 지난 쿠폰이에요.' then raise;end if;denied:=true;end;if not denied then raise exception 'expired coupon used';end if;
 update public.gym_point_coupons set expires_at=now()+interval '1 month' where id=coupon;
 perform public.onoff_points(b,jsonb_build_object('action','use','couponId',coupon,'requestId',use_id,'pin',pin));
 execute 'reset role';
 delete from auth.users where id=b;
 if exists(select 1 from public.gym_point_accounts where user_id=b) or exists(select 1 from public.gym_point_coupons where user_id=b) or exists(select 1 from public.gym_point_ledger where user_id=b) or exists(select 1 from public.gym_point_grants where user_id=b) or exists(select 1 from public.gym_coupon_uses where user_id=b) then raise exception 'withdrawal retained points/coupons';end if;
end $$;
select not has_table_privilege('authenticated','public.gym_point_rules','select') as rules_private,not has_table_privilege('authenticated','public.gym_point_grants','select') as grants_private;
rollback;
